package com.brightloop.catalog;
import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class CustomerService {
 private final CustomerRepository repo;public CustomerService(CustomerRepository r){repo=r;}
 @Transactional(readOnly=true) public Page<CatalogDtos.CustomerResponse> list(String search,Pageable p){Page<Customer> result=search==null||search.isBlank()?repo.findAll(p):repo.findByFullNameContainingIgnoreCaseOrEmailContainingIgnoreCase(search,search,p);return result.map(CatalogDtos.CustomerResponse::of);}
 @Transactional(readOnly=true) public CatalogDtos.CustomerResponse get(Long id){return CatalogDtos.CustomerResponse.of(find(id));}
 @Transactional public CatalogDtos.CustomerResponse create(CatalogDtos.CustomerRequest r){if(repo.existsByEmailIgnoreCase(r.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"A customer with this email already exists");var c=new Customer(r.fullName().trim(),r.email(),r.phone(),r.companyName(),r.billingAddress(),r.city(),r.state(),r.country(),r.postalCode(),r.taxId());return CatalogDtos.CustomerResponse.of(repo.save(c));}
 @Transactional public CatalogDtos.CustomerResponse update(Long id,CatalogDtos.CustomerRequest r){var c=find(id);if(repo.existsByEmailIgnoreCaseAndIdNot(r.email(),id))throw new ResponseStatusException(HttpStatus.CONFLICT,"A customer with this email already exists");c.update(r.fullName().trim(),r.email(),r.phone(),r.companyName(),r.billingAddress(),r.city(),r.state(),r.country(),r.postalCode(),r.taxId(),r.status()==null?"ACTIVE":r.status());return CatalogDtos.CustomerResponse.of(c);}
 @Transactional public void archive(Long id){var c=find(id);c.update(c.getFullName(),c.getEmail(),c.getPhone(),c.getCompanyName(),c.getBillingAddress(),c.getCity(),c.getState(),c.getCountry(),c.getPostalCode(),c.getTaxId(),"ARCHIVED");}
 @Transactional(readOnly=true) public CatalogDtos.CustomerResponse own(String email){return repo.findByEmailIgnoreCase(email).map(CatalogDtos.CustomerResponse::of).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer profile not found"));}
 @Transactional public CatalogDtos.CustomerResponse updateOwn(String email,String fullName,String phone,String company,String address,String city,String state,String country,String postal){var c=repo.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer profile not found"));c.update(fullName,email,phone,company,address,city,state,country,postal,c.getTaxId(),c.getStatus());return CatalogDtos.CustomerResponse.of(c);}
 private Customer find(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found"));}
}
